  const rewrite=(code:string)=>code.replace(/from (['"])([^'"]+)\1/g,(_all,quote,specifier)=>`from ${quote}${!realSampler&&specifier==='./useMprSampling.ts'?samplerStub:specifier.startsWith('.')?new URL(specifier,url).href:import.meta.resolve(specifier)}${quote}`),transpile=(code:string)=>rewrite(ts.transpileModule(code,{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText);
  const result=(await import(`data:text/javascript;base64,${Buffer.from(transpile(script.content)).toString('base64')}`)).default;result.render=(await import(`data:text/javascript;base64,${Buffer.from(transpile(template.code)).toString('base64')}`)).render;return result;
