  const data=new Float32Array(125);for(let z=0;z<5;z++)for(let y=0;y<5;y++)for(let x=0;x<5;x++)data[x+5*(y+5*z)]=x+10*y+100*z;
  const grid={dims:[5,5,5] as Vec3,spacing:[2,Math.sqrt(10),4] as Vec3,data,affine:[[2,1,0,10],[0,3,0,-4],[0,0,4,20]]},props:any=shallowReactive({volume:{...grid,name:'synthetic-MPR',unit:'mm',min:0,max:444,oblique:true},grid,plane:clonePlane(),viewId:2,mprRevision:4,step:2,interpolation:'linear',revision:7,point:[2,2,2],crosshair:mprPixelToWorld(plane,[1.2,1.4]),tool:'navigate',center:127.5,width:255,masks:[],measurements:[],measurementLabels:{},allowEdit:true,densitySize:[1,1],draftPoints:[],draftPlane:null});
