function prepareBrush(h:Awaited<ReturnType<typeof harness>>,tool='paint'){
  const mask={id:'active',name:'active',color:'#ff0000',opacity:.5,visible:true,data:new Uint8Array(h.props.grid.data.length),revision:0,threshold:null};
  Object.assign(h.props,{tool,activeMaskId:mask.id,masks:[mask],brushWidth:6,brushHeight:2,sameWidthHeight:false,brushShape:'circle'});return mask;
}

